#!/bin/bash
# Build the three manuals as PDFs.
#
#   cd sentinel-oo/docs && ./make_pdfs.sh
#
# Needs pandoc and XeLaTeX, both of which are installed on this machine.
# Everything it needs is in this repository: the diagrams are drawn images
# generated by diagrams/make_diagrams.py, so nothing is fetched and nothing
# has to be rendered by a service.
#
# The user manual absorbs the contract language and the deployment guide,
# because a link from one PDF to another file does not work, and the user
# manual links to both.

set -euo pipefail
cd "$(dirname "$0")"

OUT=pdf
mkdir -p "$OUT"

COMMON=(
  --pdf-engine=xelatex
  --listings
  --toc --toc-depth=2
  --number-sections=false
  -H latex-header.tex
  -V geometry:margin=2.2cm
  -V mainfont="Helvetica Neue"
  -V monofont="Menlo"
  -V colorlinks=true
  -V linkcolor=black
  -V urlcolor=Maroon
  -V toccolor=black
  -V date="11 November 2026"
  -V author="Anil Wipat, Newcastle University"
)

cat > latex-header.tex <<'EOF'
\usepackage{booktabs}
\setlength{\emergencystretch}{3em}
% Long lines in code blocks wrap instead of running off the page.
\lstset{breaklines=true, breakatwhitespace=false, basicstyle=\ttfamily\small,
        columns=fullflexible, keepspaces=true, showstringspaces=false}
% Pandoc 3 keeps an image inside the text block on its own, so nothing is
% needed here for that. adjustbox is not installed in this LaTeX and is not
% worth a dependency.
EOF

echo "Building the manuals."

echo "  system manual"
# The hand written Contents list is there for GitHub, which has no contents
# of its own. In the PDF pandoc builds a real one, and the hand written
# anchors do not survive the conversion, so it is stripped here.
python3 - <<'STRIP' > /tmp/sentinel-system-manual.md
import re, pathlib
t = pathlib.Path("SYSTEM_MANUAL.md").read_text()
print(re.sub(r"## Contents\n.*?\n---\n", "", t, count=1, flags=re.S), end="")
STRIP
pandoc /tmp/sentinel-system-manual.md -o "$OUT/sentinel-oo-system-manual.pdf" \
  "${COMMON[@]}" -V title="sentinel-oo: system manual" \
  --resource-path=.:diagrams
rm -f /tmp/sentinel-system-manual.md

echo "  user manual, with the contract language and deploying as chapters"
{
  cat USER_MANUAL.md
  printf '\n\n\\newpage\n\n'
  cat WRITING_A_CONTRACT.md
  printf '\n\n\\newpage\n\n'
  cat DEPLOYING.md
} > /tmp/sentinel-user-manual.md
pandoc /tmp/sentinel-user-manual.md -o "$OUT/sentinel-oo-user-manual.pdf" \
  "${COMMON[@]}" -V title="sentinel-oo: user manual"
rm -f /tmp/sentinel-user-manual.md

echo "  API manual"
pandoc API_MANUAL.md -o "$OUT/sentinel-oo-api-manual.pdf" \
  "${COMMON[@]}" -V title="sentinel-oo: API manual"

rm -f latex-header.tex
echo
ls -la "$OUT"/*.pdf
